INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural neutrofílico (PMN > 50%) em um paciente com dor abdominal aguda, febre e sinal de Murphy positivo aponta para qual diagnóstico?", "options": {"a": "Abcesso Subfrênico.", "b": "Infarto Pulmonar.", "c": "Pleurite por TB.", "d": "Amiodarona.", "e": "Toxoplasmose."}, "answer": "a", "rationale": "Qualquer processo inflamatório infradiafragmático (colecistite, abscesso hepático ou subfrênico) pode causar um ''derrame simpático'' por translocação de mediadores inflamatórios através dos linfáticos diafragmáticos. O líquido é exsudativo e predominantemente neutrofílico.", "option_rationales": {"a": "Correta. Associação clássica da pleura com o abdome agudo infeccioso.", "b": "Incorreta. Não explicaria o Murphy positivo.", "c": "Incorreta. TB é linfocítica.", "d": "Incorreta. Amiodarona causa derrame eosinofílico/linfocítico crônico.", "e": "Incorreta. Manifestação pleural da toxo é rara e não tem Murphy."}, "difficulty": "facil", "tags": ["Pneumologia", "Cirurgia", "Abdome Agudo", "Derrame Simpático"]}'::jsonb, 150, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal limitação da citometria de fluxo no líquido pleural para o diagnóstico de Linfoma?", "options": {"a": "Poucas células no líquido.", "b": "As células malignas do linfoma podem sofrer lise rápida se o transporte do líquido para o laboratório não for imediato e em frasco adequado.", "c": "Não consegue detectar linfócitos B.", "d": "É muito cara.", "e": "Só funciona no sangue periférico."}, "answer": "b", "rationale": "Linfócitos neoplásicos são frágeis. O transporte inadequado ou a demora na análise podem destruir as células, levando a resultados falso-negativos na citometria de fluxo. O ideal é o processamento imediato ou uso de meio de conservação.", "option_rationales": {"a": "Incorreta. Linfomas pleurais costumam ser muito celulares.", "b": "Correta. Limitação técnica e pré-analítica crítica.", "c": "Incorreta. Detecta perfeitamente através de marcadores de superfície (CD19, CD20, etc).", "d": "Incorreta. Embora cara, a limitação biológica/técnica citada é mais relevante no diagnóstico falho.", "e": "Incorreta. Funciona muito bem em serosas (líquidos cavitários)."}, "difficulty": "media", "tags": ["Pneumologia", "Hematologia", "Linfoma", "Citometria"]}'::jsonb, 151, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o manejo da Pleurite Tuberculosa, qual o papel do uso adjuvante de Corticosteroides sistêmicos?", "options": {"a": "Reduzem o tempo de cura bacteriológica.", "b": "Reduzem a febre e a dor mais rapidamente, mas não há evidência robusta de que previnam o espessamento pleural residual significativo a longo prazo.", "c": "São obrigatórios para todos os pacientes visando esterilização da pleura.", "d": "Substituem a rifampicina nos primeiros 2 meses.", "e": "Causam cegueira se usados com etambutol."}, "answer": "b", "rationale": "O uso de corticoide (Prednisona) pode ser feito para alívio rápido de sintomas (febre, dor) em pacientes muito sintomáticos. No entanto, meta-análises mostram que não há benefício claro na prevenção de fibrose pleural sequelar ou melhora da função pulmonar final em comparação ao esquema RIPE isolado.", "option_rationales": {"a": "Incorreta. Corticoides podem até retardar o clearance se não usados com TB sensível.", "b": "Correta. Consenso atual baseado em evidências de ensaios clínicos.", "c": "Incorreta. Não são obrigatórios.", "d": "Incorreta. Não substituem o esquema bactericida/esterilizante.", "e": "Incorreta. Etambutol causa neurite óptica isoladamente; corticoide não agrava essa toxicidade específica desta forma."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Terapêutica", "Corticoides"]}'::jsonb, 152, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O ''Derrame Pleural Benigno do Asbesto'' (BAPE) é frequentemente asssintomático. No entanto, quando acompanhado de dor torácica persistente e evolução para espessamento pleural fibrótico difuso, pode mimetizar:", "options": {"a": "Tuberculose Pleural.", "b": "Mesotelioma Maligno.", "c": "Pneumonia bacteriana.", "d": "Embolia pulmonar recorrente.", "e": "Sarcoidose estágio IV."}, "answer": "b", "rationale": "A grande dificuldade diagnóstica do BAPE crônico e fibrótico é diferenciá-lo do mesotelioma em fase inicial. Ambas ocorrem em pacientes expostos ao asbesto e podem causar dor crônica. Muitas vezes apenas a videotoracoscopia com múltiplas biópsias profundas consegue selar o diagnóstico.", "option_rationales": {"a": "Incorreta. TB regride com tratamento; o BAPE fibrosa ou cicatriza sozinho.", "b": "Correta. Principal desafio diagnóstico diferencial na medicina ocupacional torácica.", "c": "Incorreta. Quadro agudo com febre.", "d": "Incorreta. TEP não causa espessamento pleural fibrótico difuso.", "e": "Incorreta. Sarcoidose IV é predominantemente fibrose parenquimatosa."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Derrame do Asbesto", "Mesotelioma"]}'::jsonb, 153, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do Intervalo entre os batimentos no eletrocardiograma (Intervalo QT) pode sofrer interferência em qual tipo de derrame cavitário?", "options": {"a": "Apenas derrame pleural esquerdo.", "b": "Derrame Pleural Bilateral volumoso.", "c": "Derrame Pericárdico (mimetiza baixa voltagem, mas não altera o QT intrinsicamente, exceto por distúrbios de repolarização associados).", "d": "Não há interferência do derrame pleural no ECG.", "e": "Apenas urinotórax."}, "answer": "c", "rationale": "Embora o derrame pleural possa causar baixa voltagem nos complexos QRS, as alterações de tempo (QT) são raras e indiretas (ex: hipocalcemia no quilotórax ou hipocalemia). A questão foca na confusão clássica com a pericardite associada ( Dressler) que altera o segmento ST e a onda T.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Derrame pleural volumoso reduz a voltagem, mas o QT é alterado por serosites ou eletrólitos.", "d": "Incorreta. Existe interferência na voltagem.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "ECG", "Derrame Pleural", "Interferências"]}'::jsonb, 154, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O Mesotelioma Peritoneal Maligno se manifesta por ascite e dor abdominal. Qual a relação dele com a exposição ao asbesto em comparação ao Mesotelioma Pleural?", "options": {"a": "O peritoneal exige cargas de exposição ao asbesto muito maiores que o pleural.", "b": "O peritoneal não tem relação com o asbesto.", "c": "O peritoneal ocorre mais em mulheres que nunca viram amianto.", "d": "São doenças idênticas em todos os aspectos epidemiológicos.", "e": "O peritoneal é curado com antibióticos."}, "answer": "a", "rationale": "Ambos são causados pelo asbesto, mas o mesotelioma peritoneal (que representa cerca de 10-15% dos mesoteliomas) geralmente está associado a exposições ocupacionais pesadas e prolongadas, enquanto o pleural pode ocorrer com exposições menores.", "option_rationales": {"a": "Correta. Diferença de ''threshold'' de exposição entre as duas serosas.", "b": "Incorreta. Amianto é a causa principal de ambos.", "c": "Incorreta. Predomina em homens expostos ocupacionalmente.", "d": "Incorreta. Locais diferentes, prognóstico e algoritmos de tratamento cirúrgico (ex: HIPEC no peritoneal) diferentes.", "e": "Incorreta. É uma neoplasia maligna agressiva."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma Peritoneal", "Asbesto"]}'::jsonb, 155, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No paciente com cirrose e derrame pleural bilateral, a ocorrência de febre e dor torácica deve levantar a suspeita de Pleurite Bacteriana Espontânea (SBPE). Qual o micro-organismo MAIS FREQUENTEMENTE isolado nesta condição?", "options": {"a": "Staphylococcus aureus.", "b": "Escherichia coli.", "c": "Mycobacterium avium.", "d": "Pseudomonas aeruginosa.", "e": "Legionella pneumophila."}, "answer": "b", "rationale": "Assim como na Peritonite Bacteriana Espontânea (PBE), a SBPE é causada majoritariamente por enterobactérias gram-negativas (E. coli, Klebsiella), resultantes da translocação bacteriana intestinal.", "option_rationales": {"a": "Incorreta. Mais comum em infecções de pele ou pós-procedimentos.", "b": "Correta. Agente clássico da translocação no cirrótico.", "c": "Incorreta. Germe oportunista raro.", "d": "Incorreta. Germe hospitalar, menos comum na SBPE comunitária pura.", "e": "Incorreta. Causa de pneumonia comunitária grave, não de SBPE."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Cirrose", "Infectologia"]}'::jsonb, 156, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Eosinofílica'' (Eosinófilos > 10%) torna qual diagnóstico EXTREMAMENTE IMPROVÁVEL?", "options": {"a": "Câncer de pulmão.", "b": "Tuberculose Pleural e TEP.", "c": "Tuberculose Pleural (apenas).", "d": "Linfoma.", "e": "Reação a drogas."}, "answer": "c", "rationale": "Embora existam exceções raras, encontrar eosinofilia importante no líquido pleural fala fortemente contra o diagnóstico de Tuberculose Pleural. Essa ''regra prática'' ajuda a priorizar outros exsudatos linfocíticos na ausência de eosinofilia.", "option_rationales": {"a": "Incorreta. Câncer pode dar eosinófilos.", "b": "Incorreta. TEP frequentemente cursa com eosinofilia pleural.", "c": "Correta. Regra propedêutica clássica de exclusão (ou baixíssima probabilidade) de TB.", "d": "Incorreta. Alguns linfomas (T) podem dar eosinófilos.", "e": "Incorreta. Drogas são causas comuns de eosinofilia."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Derrame Eosinofílico", "Exclusão TB"]}'::jsonb, 157, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a causa de derrame pleural volumoso à esquerda que apresenta níveis de lipase pleural superiores aos níveis séricos?", "options": {"a": "Pancreatite.", "b": "Ruptura de Baço.", "c": "Perfuração de Duodeno.", "d": "Câncer de Cólon.", "e": "Hérnia Diafragmática de Bochdalek infectada."}, "answer": "a", "rationale": "A amilase e a lipase pleurais elevadas são marcadores de patologia pancreática (pancreatite aguda ou pseudocisto). A enzima vaza para o espaço pleural pela via linfática transdiafragmática ou por fístulas.", "option_rationales": {"a": "Correta. Marcador bioquímico específico.", "b": "Incorreta. Baço não produz lipase digestiva.", "c": "Incorreta. Duodeno recebe lipase, mas sua ruptura dificilmente daria um derrame pleural isolado com este perfil sem um quadro abdominal catastrófico e amilase salivar.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Bioquímica", "Pancreatite", "Lipase"]}'::jsonb, 158, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciate": "Em relação aos tumores pleurais, o Mesotelioma benigno (atualmente chamado de Tumor Fibroso Solitário da Pleura - TFSP) apresenta qual característica imunológica que o distingue de outros tumores mesenquimais?", "options": {"a": "Positividade para o marcador STAT6.", "b": "Hipersensibilidade ao talco.", "c": "Expressão de Receptor de Estrogênio em todos os casos.", "d": "Sempre CD20 positivo.", "e": "Ausência de colágeno na biópsia."}, "answer": "a", "rationale": "A mutação de fusão NAB2-STAT6 é o evento genético driver do Tumor Fibroso Solitário. A positividade nuclear para STAT6 na imuno-histoquímica é o exame padrão-ouro para confirmar o diagnóstico deste tumor fibroblástico.", "option_rationales": {"a": "Correta. Marcador diagnóstico específico de biologia molecular.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta. CD20 é linfócito B.", "e": "Incorreta. São tumores ricos em colágeno (fibrosos)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "TFSP", "STAT6"]}'::jsonb, 159, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 45 anos, em tratamento para Leucemia Mieloide Crônica (LMC) com o inibidor de tirosina quinase de segunda geração Dasatinibe, desenvolve dispneia progressiva e derrame pleural bilateral exsudativo. Qual é o mecanismo fisiopatológico mais aceito para este efeito colateral comum desta medicação?", "options": {"a": "Bloqueio do canal de cálcio pleural.", "b": "Inibição de quinases (como SRC) levando ao aumento da permeabilidade vascular e disfunção endotelial pleural.", "c": "Cardiotoxicidade com fração de ejeção de 20%.", "d": "Indução de Linfoma T secundário.", "e": "Toxicidade direta da medicação contra as células mesoteliais causando necrose."}, "answer": "b", "rationale": "O Dasatinibe é conhecido por causar derrame pleural em até 15-30% dos pacientes. O mecanismo envolve a inibição das quinases da família SRC, que regulam a permeabilidade das junções endoteliais. O tratamento consiste na suspensão temporária da droga ou redução da dose, associada ou não ao uso de corticoides.", "option_rationales": {"a": "Incorreta. Não é o mecanismo descrito.", "b": "Correta. Mecanismo de toxicidade endotelial farmacológica clássico.", "c": "Incorreta. O derrame pelo dasatinibe é exsudativo e ocorre mesmo com função cardíaca preservada.", "d": "Incorreta. Tratamento da leucemia não causa linfoma T de forma aguda como mecanismo de derrame.", "e": "Incorreta. Não há necrose mesotelial primária, mas sim aumento da permeabilidade."}, "difficulty": "media", "tags": ["Pneumologia", "Hematologia", "Dasatinibe", "Iatrogenia"]}'::jsonb, 160, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurodese Espontânea'' ou ''Autopleurodese'' pode ocorrer em qual situação clínica, muitas vezes evitando a necessidade de intervenção cirúrgica?", "options": {"a": "Após uma única toracentese diagnóstica pequena.", "b": "Em pacientes com cateter pleural de demora (IPC), devido à inflamação crônica causada pelo trajeto do cateter e pela drenagem contínua do líquido.", "c": "Em pacientes tabagistas.", "d": "Sempre que houver transudato cardíaco.", "e": "No uso de amoxicilina oral."}, "answer": "b", "rationale": "Cerca de 40-50% dos pacientes que usam cateter pleural de demora (IPC) para derrame maligno acabam desenvolvendo sínfise pleural espontânea após alguns meses. Isso permite a retirada do cateter, pois o espaço pleural deixa de existir devido à reação inflamatória crônica ao corpo estranho e à aposição das pleuras.", "option_rationales": {"a": "Incorreta. Uma punção raramente causa sínfise.", "b": "Correta. Fenômeno observado em pacientes com dreno de longa permanência.", "c": "Incorreta. O tabaco causa enfisema, não pleurodese.", "d": "Incorreta. Transudatos não inflamam a pleura para causar sínfise.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Cateter Pleural", "Pleurodese"]}'::jsonb, 161, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No ultrassom de tórax, a presença do ''Sinal do Plâncton'' (Plankton Sign) — partículas flutuantes e móveis dentro do líquido pleural — sugere fortemente qual natureza do derrame?", "options": {"a": "Transudato simples (água pura).", "b": "Líquido rico em detritos celulares, proteínas ou sangue (ex: empiema, hemotórax ou derrame maligno).", "c": "Pneumotórax.", "d": "Cisto hidático roto.", "e": "Derrame de colesterol apenas."}, "answer": "b", "rationale": "Líquidos anecoicos (pretos) no US costumam ser transudatos. Quando há ecogenicidade interna (pontos brilhantes que se movem como plâncton), isso indica um exsudato com alta celularidade ou conteúdo proteico/hemático, ajudando o clínico a guiar a suspeita diagnóstica antes mesmo da bioquímica.", "option_rationales": {"a": "Incorreta. Transudatos são tipicamente anecoicos e ''limpos''.", "b": "Correta. Marcador ultrassonográfico de exsudato complexo.", "c": "Incorreta. Pneumotórax impede a visualização de líquido.", "d": "Incorreta. Cisto hidático tem membranas flutuantes (''sinal do lírio d''água''), não plâncton fino.", "e": "Incorreta. Derrame de colesterol tem cristais que dão um padrão de ''neve'' (snowstorm), mas o plâncton é mais geral para qualquer exsudato turvo."}, "difficulty": "media", "tags": ["Pneumologia", "Ultrassonografia", "Semiologia", "Exsudato"]}'::jsonb, 162, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente gestante (30 semanas) apresenta dispneia intensa, edema de face e membros, associado a hipertensão arterial (170/110 mmHg). A radiografia de tórax revela derrame pleural bilateral e edema pulmonar. Qual a causa mais provável deste derrame pleural?", "options": {"a": "Pneumonia comunitária grave.", "b": "Preeclâmpsia com edema agudo de pulmão e anasarca.", "c": "Embolia amniótica.", "d": "Síndrome de Meigs gestacional.", "e": "Tuberculose reativada na gestação."}, "answer": "b", "rationale": "A preeclâmpsia grave causa disfunção endotelial sistêmica, aumento da permeabilidade capilar e queda da pressão oncótica (pela proteinúria). Isso resulta em derrames cavitários (pleural, ascite) e edema alveolar, sendo uma causa importante de insuficiência respiratória no terceiro trimestre.", "option_rationales": {"a": "Incorreta. Menos comum que a preeclâmpsia no contexto de hipertensão aguda.", "b": "Correta. Complicação obstétrica sistêmica clássica.", "c": "Incorreta. Quadro catastrófico de choque cardiogênico e CIVD súbita durante o trabalho de parto.", "d": "Incorreta. Meigs é associado a tumores benignos de ovário, não à hipertensão gestacional.", "e": "Incorreta. A TB não explica a hipertensão aguda e o edema generalizado súbito."}, "difficulty": "facil", "tags": ["Pneumologia", "Obstetrícia", "Preeclâmpsia", "Derrame na Gravidez"]}'::jsonb, 163, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Fascite Eosinofílica'' (Síndrome de Shulman) pode cursar com qual manifestação torácica em cerca de 10% dos casos?", "options": {"a": "Nódulos pulmonares gigantes.", "b": "Derrame pleural exsudativo com alta eosinofilia.", "c": "Pneumotórax bilateral.", "d": "Fístula traqueoesofágica.", "e": "Calcificação da traqueia."}, "answer": "b", "rationale": "A fascite eosinofílica é uma doença esclerodermiforme rara. O envolvimento sistêmico pode incluir derrames pleurais que refletem a marca da doença: a eosinofilia. É um diagnóstico diferencial importante em derrames eosinofílicos de causa sistêmica ignorada.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manifestação serosa rara mas descrita da doença.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Eosinofilia", "Fascite"]}'::jsonb, 164, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com empiema organizado (espessamento pleural denso - ''Casca Pleural''), por que o uso de fibrinolíticos ou dreno de tórax simples costuma falhar?", "options": {"a": "Porque as bactérias são resistentes aos antibióticos dentro da casca.", "b": "Porque o pulmão está ''aprisionado'' por uma membrana de tecido fibroso denso que impede sua reexpansão (Pulmão Encarcerado), mesmo que o líquido seja retirado.", "c": "Porque o dreno causa mais infecção.", "d": "Porque o pus se transforma em gordura.", "e": "Porque a pleura visceral desaparece."}, "answer": "b", "rationale": "Na fase organizada do empiema (Fase 3), a deposição de colágeno e fibroblastos cria uma carapaça rígida sobre a pleura visceral. Isso impede o pulmão de inflar e encostar na parede torácica. O problema aqui é mecânico, exigindo decorticação cirúrgica para retirar a casca e liberar o pulmão.", "option_rationales": {"a": "Incorreta. Embora a penetração do atb seja ruim, o problema principal para a resolução radiológica é a falta de expansão pulmonar.", "b": "Correta. Definição fisiopatológica do pulmão encarcerado sequelar ao empiema.", "c": "Incorreta. O dreno é necessário, mas insuficiente na fase fibrótica crônica.", "d": "Incorreta. Pus não vira gordura.", "e": "Incorreta. A pleura visceral está espessada, não ausente."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Pulmão Encarcerado"]}'::jsonb, 165, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural volumoso ''marrom escuro'' ou ''achocolatado'' após um trauma hepático ou em um paciente com abscesso hepático amebiano sugere fístula hepatopleural. Qual o agente causal clássico?", "options": {"a": "Entamoeba histolytica.", "b": "Giardia lamblia.", "c": "Ascaris lumbricoides.", "d": "Schistosoma hematobium.", "e": "Trypanosoma cruzi."}, "answer": "a", "rationale": "O abscesso amebiano hepático pode romper para o espaço pleural (geralmente à direita). O líquido é classicamente descrito como ''pasta de anchovas'' ou ''achocolatado'', composto de tecido hepático necrótico e sangue digerido. É uma complicação grave da amebíase extraintestinal.", "option_rationales": {"a": "Correta. Agente da amebíase invasiva hepática/pleural.", "b": "Incorreta. Não causa abscessos hepáticos ou derrames.", "c": "Incorreta. Causa ciclo de Loeffler no parênquima, não abscessos achocolatados.", "d": "Incorreta. Acomete sistema urinário.", "e": "Incorreta. Causa miocardite/megaesôfago."}, "difficulty": "facil", "tags": ["Pneumologia", "Infectologia", "Amebíase", "Abscesso Hepático"]}'::jsonb, 166, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Tuberculose Pleural em pacientes com HIV/AIDS com contagem de CD4 < 100 células/mm³, qual a principal mudança observada no perfil do líquido pleural em comparação ao paciente imunocompetente?", "options": {"a": "O derrame torna-se transudativo.", "b": "A baciloscopia (BAAR) e a cultura do líquido tornam-se POSITIVAS com mais frequência, devido à maior carga bacilar e menor resposta granulomatosa defensiva.", "c": "O ADA cai para zero.", "d": "Não existe TB pleural no HIV.", "e": "Ocorrência obrigatória de pneumotórax junto ao derrame."}, "answer": "b", "rationale": "Em imunodeprimidos graves, a resposta de hipersensibilidade (granuloma) que normalmente mantém o líquido paucibacilar falha. Isso leva a uma disseminação hematogênica ou linfática mais intensa para a pleura, resultando em maior número de bacilos no líquido, facilitando o diagnóstico direto (BAAR/Cultura/TRM-TB).", "option_rationales": {"a": "Incorreta. Continua sendo exsudato inflamatório.", "b": "Correta. Paradoxalmente, o diagnóstico microbiológico direto é mais fácil no HIV muito avançado.", "c": "Incorreta. O ADA pode continuar alto ou sofrer pouca variação.", "d": "Incorreta. É uma manifestação muito comum.", "e": "Incorreta. Não é regra."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "HIV/AIDS", "Tuberculose"]}'::jsonb, 167, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal indicação para a realização de angiografia por tomografia (Angio-TC) em um paciente com hemotórax traumático drenado que persiste com drenagem > 200 mL/hora por 3 horas consecutivas?", "options": {"a": "Identificar sangramento ativo de vasos da parede (ex: artéria intercostal ou mamária interna) para possível embolização ou planejamento cirúrgico.", "b": "Rastrear embolia pulmonar simultânea.", "c": "Verificar se o dreno é de boa marca.", "d": "Diagnosticar pneumonia associada.", "e": "Apenas por rotina administrativa."}, "answer": "a", "rationale": "Drenagem persistente e volumosa (> 200 mL/h) indica sangramento arterial ativo. A Angio-TC ou a arteriografia ajudam a localizar o vaso sangrante antes da toracotomia de emergência ou para permitir a embolização por radiologia intervencionista em casos selecionados.", "option_rationales": {"a": "Correta. Indicação de imagem para urgência vascular torácica.", "b": "Incorreta. TEP não causa hemotórax maciço de 200mL/h.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Cirurgia de Trauma", "Hemotórax", "Diagnóstico"]}'::jsonb, 168, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A síndrome de ''Mounier-Kuhn'' (Traqueobroncomegalia) associa-se a infecções respiratórias recorrentes. Qual a sua relação potencial com patologias pleurais?", "options": {"a": "Não tem nenhuma relação.", "b": "Pode levar a episódios repetidos de derrame parapneumônico e empiema devido à bronquiectasia grave e falha no clearance de secreções.", "c": "Causa mesotelioma precocemente.", "d": "Leva à calcificação do diafragma.", "e": "É a principal causa de quilotórax."}, "answer": "b", "rationale": "A dilatação excessiva da traqueia e brônquios (por atrofia de fibras elásticas) causa estase de secreção e bronquiectasias. Isso predispõe a pneumonias graves recorrentes, que por sua vez podem complicar com derrames pleurais e empiemas de repetição.", "option_rationales": {"a": "Incorreta. Doenças das vias aéreas impactam o espaço pleural via infecção.", "b": "Correta. Nexo clínico via complicações infecciosas pulmonares.", "c": "Incorreta. Mesotelioma é ambiental (asbesto).", "d": "Incorreta.", "e": "Incorreta. Quilotórax é doença linfática."}, "difficulty": "media", "tags": ["Pneumologia", "Vias Aéreas", "Empiema", "Bronquiectasia"]}'::jsonb, 169, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista com câncer de pulmão apresenta-se com Síndrome da Veia Cava Superior (SVCS). Ele desenvolve derrame pleural bilateral. A análise do líquido revela um TRANSUDATO. Qual o mecanismo?", "options": {"a": "Metástase pleural massiva.", "b": "Aumento da pressão hidrostática nos capilares pleurais devido à obstrução da drenagem venosa sistêmica cranial (veias braquiocefálicas/cava superior).", "c": "Desnutrição neoplásica grave.", "d": "Pneumonia pós-obstrutiva.", "e": "Insuficiência cardíaca direita por TEP."}, "answer": "b", "rationale": "A SVCS aumenta a pressão hidrostática nas veias que drenam a pleura parietal superior e mediastinal. Isso pode gerar um transudato puramente mecânico, independente da presença de metástases pleurais. Ao tratar a obstrução (stent ou radio), o derrame costuma desaparecer.", "option_rationales": {"a": "Incorreta. Metástase daria exsudato.", "b": "Correta. Mecanismo hidrostático clássico da obstrução venosa central.", "c": "Incorreta. Desnutrição (hipoalbuminemia) daria transudato, mas a SVCS é uma causa mecânica mais direta neste contexto.", "d": "Incorreta. Pneumonia daria exsudato parapneumônico.", "e": "Incorreta. Hipótese menos provável se houver sinais claros de obstrução de cava (turgência jugular que não pulsa, edema em escravina)."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "SVCS", "Mecanismo"]}'::jsonb, 170, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do ''tempo de protrombina'' (TAP/INR) e ''tempo de tromboplastina parcial ativada'' (TTPA) no Líquido Pleural é recomendada?", "options": {"a": "Sim, para avaliar risco de sangramento local.", "b": "Não, pois o líquido pleural é naturalmente deficiente em fatores de coagulação e os valores não têm correlação com o risco de sangramento clínico ou status sistêmico.", "c": "Apenas se o paciente usar Varfarina.", "d": "Sim, substitui a coleta de sangue periférico.", "e": "Mandatório no empiema."}, "answer": "b", "rationale": "Os testes de coagulação são padronizados para o plasma. O líquido pleural (especialmente após desfibrinação no hemotórax) não possui os mesmos níveis de proteínas da cascata, tornando a dosagem desses tempos no líquido inúteis e tecnicamente inválidas.", "option_rationales": {"a": "Incorreta. O risco é avaliado no sangue periférico.", "b": "Correta. Inutilidade clínica do teste no compartimento pleural.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Bioquímica", "Coagulação"]}'::jsonb, 171, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em qual das seguintes condições a pleura parietal apresenta tipicamente um aspecto de ''renda'' ou ''favas de mel'' na inspeção direta por videotoracoscopia?", "options": {"a": "Início da Tuberculose Pleural.", "b": "Linfangiomatose pleuropulmonar difusa ou Linfangiomatose capilar.", "c": "Insuficiência Cardíaca pura.", "d": "Empiema bacteriano.", "e": "Silicose aguda."}, "answer": "b", "rationale": "A proliferação anômala de canais linfáticos na pleura (linfangiomatose) cria um padrão reticular e multicístico visível macroscopicamente, frequentemente associado a derrames quilosos recorrentes.", "option_rationales": {"a": "Incorreta. TB dá nódulos esbranquiçados (grânulos de milho).", "b": "Correta. Descrição morfológica de distúrbios linfáticos pleurais.", "c": "Incorreta. Pleura lisa.", "d": "Incorreta. Pleura recoberta por fibrina amarelada.", "e": "Incorreta. Silicose atinge pouco a pleura isoladamente comparada ao pulmão."}, "difficulty": "dificil", "tags": ["Pneumologia", "Linfologia", "VATS", "Morfologia"]}'::jsonb, 172, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de Soluble Mesothelin-Related Peptides (SMRP) no líquido pleural é um biomarcador promissor para o diagnóstico de qual patologia?", "options": {"a": "Artrite Reumatoide.", "b": "Mesotelioma Maligno.", "c": "Pneumonia por Legionella.", "d": "Tuberculose Pleural.", "e": "Cancer de Próstata."}, "answer": "b", "rationale": "O SMRP é liberado por células mesoteliais neoplásicas. Embora sua sensibilidade não seja perfeita, altos níveis no líquido pleural têm alta especificidade para o mesotelioma epitelioide.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Biomarcador específico para neoplasia mesotelial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Biomarcadores", "Mesotelioma", "SMRP"]}'::jsonb, 173, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a ''Linfocitose Pleural'' (> 50-80%), qual a causa MAIS COMUM em países com alta prevalência de Tuberculose?", "options": {"a": "Cancer de pulmão.", "b": "Tuberculose Pleural.", "c": "Linfoma.", "d": "Artrite Reumatoide.", "e": "Sarcoidose."}, "answer": "b", "rationale": "Embora o câncer e o linfoma também causem linfocitose, em países endêmicos para Mycobacterium tuberculosis como o Brasil, a TB pleural é estatisticamente a causa número 1 de exsudato linfocítico persistente em jovens e adultos jovens.", "option_rationales": {"a": "Incorreta. Comum, mas TB supera em incidência de linfocitose em muitos cenários brasileiros.", "b": "Correta. Epidemiologia clássica.", "c": "Incorreta. Mais raro comparado à TB.", "d": "Incorreta. Causa importante, mas menos frequente.", "e": "Incorreta. Rara no Brasil comparada à TB."}, "difficulty": "facil", "tags": ["Pneumologia", "Epidemiologia", "Tuberculose", "Linfocitose"]}'::jsonb, 174, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de ''Pneumoempiema'' (ar e pus no espaço pleural) sem intervenção médica prévia (toracentese/drenagem) é indicativa de:", "options": {"a": "Infecção por vírus sincicial respiratório.", "b": "Fístula Broncopleural ou ruptura de abscesso pulmonar para a pleura.", "c": "Asma brônquica grave.", "d": "Simples efeito da gravidade.", "e": "Bronquite crônica."}, "answer": "b", "rationale": "A presença de gás no espaço pleural (hidropneumotórax) na ausência de trauma ou iatrogenia indica que há uma comunicação entre a via aérea (pulmão) e a pleura (fístula), ou que o micro-organismo causador da infecção é produtor de gás (ex: Clostridium ou algumas enterobactérias).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação mecânica de pneumonia/abscesso cavitado.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Fístula"]}'::jsonb, 175, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciate": "No tratamento do empiema pleural agudo, qual o principal objetivo da fisioterapia respiratória?", "options": {"a": "Eliminar as bactérias através da tosse.", "b": "Prevenir a atelectasia reflexa, auxiliar na reexpansão pulmonar e manter a mobilidade da caixa torácica e diafragma durante a drenagem.", "c": "Substituir o uso de antibióticos.", "d": "Aumentar a produção de pus para facilitar a drenagem.", "e": "Curar a pneumonia viral associada."}, "answer": "b", "rationale": "A fisioterapia não cura a infecção (papel do atb e dreno), mas é vital para garantir que o pulmão reexpanda e preencha o espaço pleural, evitando a cronificação do empiema e perda funcional duradoura por encarceramento ou rigidez da parede torácica.", "option_rationales": {"a": "Incorreta. Tosse limpa brônquios, não a pleura (espaço fechado).", "b": "Correta. Papel fundamental da reabilitação precoce.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Reabilitação", "Empiema", "Fisioterapia"]}'::jsonb, 176, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurodese Medicinal'' com Doxiciclina ou Minociclina é uma alternativa ao talco. Qual é a principal desvantagem desses agentes químicos?", "options": {"a": "Causam escurecimento dos dentes para sempre.", "b": "Menor taxa de sucesso na sínfise pleural (cerca de 60-70%) em comparação ao talco (85-90%) e maior dor local.", "c": "São absorvidos e causam hepatite tóxica.", "d": "Não existem no Brasil.", "e": "Só podem ser usados em crianças."}, "answer": "b", "rationale": "Agentes esclerosantes derivados de tetraciclinas são menos potentes que o talco para gerar a fibrose sínfiseal necessária e costumam causar muita dor pleural durante a instilação, exigindo anestesia local potente ou sedação.", "option_rationales": {"a": "Incorreta. Isso ocorre por uso oral em crianças em fase de dentição, não por uso pleural.", "b": "Correta. Eficácia inferior documentada.", "c": "Incorreta. Absorção sistêmica é desprezível para causar hepatite.", "d": "Incorreta. Estão disponíveis.", "e": "Incorreta. Uso em adultos para pleurodese paliativa."}, "difficulty": "media", "tags": ["Pneumologia", "Pleurodese", "Doxiciclina", "Terapêutica"]}'::jsonb, 177, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente com derrame pleural por Tuberculose apresenta citologia com predomínio de linfócitos, mas baixa porcentagem de células NK (Natural Killer). Este achado correlaciona-se com:", "options": {"a": "Curatela rápida.", "b": "Mecanismo imunitário local focado em linfócitos T CD4 efetores, sendo o perfil TH1 (IFN-gama) o dominante na patogênese.", "c": "Presença de vírus Influenza.", "d": "Indicação de transplante de medula.", "e": "Inexistência de bacilos."}, "answer": "b", "rationale": "A TB pleural é o arquétipo da resposta imune celular TH1. A pleura fica repleta de linfócitos T CD4 que produzem interferon-gama, ativando macrófagos para formar granulomas. As células NK participam, mas o motor da inflamação é o linfócito T antígeno-específico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Imunologia da serosite tuberculosa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Imunologia", "Tuberculose", "Linfócitos"]}'::jsonb, 178, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A interrupção súbita do tratamento para derrame pleural por Artrite Reumatoide com doses altas de corticoide pode levar a:", "options": {"a": "Resolução completa do quadro.", "b": "Recorrência exuberante do derrame e risco de insuficiência adrenal secundária.", "c": "Cura da Artrite nas articulações.", "d": "Melhora do pH pleural.", "e": "Transformação em transudato."}, "answer": "b", "rationale": "Assim como em qualquer doença autoimune tratada com corticoides, o desmame deve ser gradual para evitar o efeito rebote da pleurite e para permitir a recuperação do eixo hipotálamo-hipófise-adrenal do paciente.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Preceito básico de manejo de corticoterapia sistêmica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Reumatologia", "Corticosteroides", "Manejo"]}'::jsonb, 179, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 62 anos, com diagnóstico de Melanoma Metastático em tratamento com Pembrolizumabe (anti-PD1), apresenta-se com dispneia e derrame pleural bilateral exsudativo, após 3 meses de terapia. Não há evidência de progressão tumoral nos outros sítios. A análise do líquido mostra linfocitose e ADA normal. Este quadro é compatível com:", "options": {"a": "Progressão explosiva da doença (Pseudoprogressão).", "b": "Evento Adverso Imuno-Relacionado (irAE), manifestando-se como pleurite autoimune induzida pelo inibidor de checkpoint.", "c": "Tuberculose reativada pela imunoterapia.", "d": "Empiema bacteriano.", "e": "Toxicidade cardíaca direta pela quimioterapia convencional."}, "answer": "b", "rationale": "Inibidores de checkpoint (como Pembrolizumabe e Nivolumabe) podem causar inflamação em qualquer órgão, incluindo a pleura. O diagnóstico de pleurite imuno-relacionada é feito pela exclusão de causas infecciosas e neoplásicas, e o tratamento geralmente envolve a suspensão da droga e o uso de corticosteroides.", "option_rationales": {"a": "Incorreta. Pseudoprogressão é o aumento temporário do tumor antes da resposta, mas a pleurite isolada sem progressão nodal ou de massa é mais sugestiva de irAE.", "b": "Correta. Manifestação moderna de toxicidade de novas terapias oncológicas.", "c": "Incorreta. Embora possível, a imunoterapia não é o gatilho clássico para TB comparado a anti-TNF.", "d": "Incorreta. Teria neutrofilia e pH baixo.", "e": "Incorreta. Imunoterapia não é quimioterapia convencional; a disfunção cardíaca (miocardite) é rara e daria transudato."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Imunoterapia", "Toxicidade"]}'::jsonb, 180, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Erdheim-Chester Disease'' é uma histiocitose de células não-Langerhans rara. Qual o achado radiológico extratorácico clássico que, se associado a derrame pleural e espessamento pleural, sugere o diagnóstico?", "options": {"a": "Nódulos hepáticos gigantes.", "b": "Infiltração perirrenal (''Hairy Kidney'' - rim cabeludo) e osteosclerose bilateral de ossos longos.", "c": "Cistos renais simples.", "d": "Escoliose grave.", "e": "Agenesia de baço."}, "answer": "b", "rationale": "A doença de Erdheim-Chester é uma neoplasia mieloide multissistêmica. O envolvimento pleural (espessamento e derrame) ocorre em até 20% dos casos. O achado patognomônico é a infiltração de gordura perirrenal por histiócitos (Hairy Kidney) e a esclerose óssea simétrica em fêmur ou tíbia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Associação clínica rara mas clássica em provas de alto nível.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Hematologia", "Erdheim-Chester", "Radiologia"]}'::jsonb, 181, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Manometria Pleural'' é uma técnica utilizada durante a toracocentese para medir a pressão no espaço pleural. Qual o principal objetivo clínico desta medição?", "options": {"a": "Substituir a radiografia de tórax.", "b": "Identificar precocemente o ''Pulmão Encarcerado'' (através da medida da elastância pleural elevada) e prevenir o edema de reexpansão ou dor intratável durante a drenagem.", "c": "Verificar se o paciente está com soluços.", "d": "Diagnosticar asma.", "e": "Calibrar o ventilador mecânico."}, "answer": "b", "rationale": "A manometria mede a queda da pressão pleural à medida que o líquido é removido. Se a pressão cair muito rápido (alta elastância), significa que o pulmão não consegue expandir para preencher o espaço (encarceramento). Isso alerta o médico para interromper o procedimento antes que ocorra laceração pulmonar ou edema de reexpansão grave.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Utilidade fisiológica aplicada à segurança do procedimento.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Procedimentos", "Manometria Pleural", "Fisiologia"]}'::jsonb, 182, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente jovem, sexo feminino, em tratamento de infertilidade com indutores de ovulação, apresenta dor abdominal, ascite e derrame pleural bilateral volumoso. Qual a fisiopatologia deste quadro (Síndrome de Hiperestimulação Ovariana - OHSS)?", "options": {"a": "Infecção pélvica disseminada.", "b": "Aumento maciço da permeabilidade vascular sistêmica mediado por VEGF e citocinas ovarianas, levando a extravasamento de líquido para terceiros espaços.", "c": "Insuficiência cardíaca pós-parto.", "d": "Metástases de coriocarcinoma.", "e": "Torção de ovário purulenta."}, "answer": "b", "rationale": "A OHSS é uma complicação grave da estimulação ovariana. O excesso de folículos produz mediadores (especialmente VEGF) que causam ''vazamento capilar'' sistêmico. O resultado é hemoconcentração, ascite e derrames pleurais (muitas vezes à direita ou bilateral).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo molecular de permeabilidade endotelial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "OHSS", "VEGF"]}'::jsonb, 183, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de Antígeno Carcinoembrionário (CEA) no líquido pleural apresenta qual utilidade prática no diagnóstico de adenocarcinoma de pulmão?", "options": {"a": "Substitui a biópsia pleural.", "b": "Valores muito elevados (ex: > 5-10 ng/mL) no líquido sugerem fortemente malignidade, aumentando a sensibilidade diagnóstica quando combinada com a citologia oncótica.", "c": "É o marcador específico de Tuberculose.", "d": "Indica infecção por fungos.", "e": "Identifica pacientes que responderão ao tabaco."}, "answer": "b", "rationale": "O CEA pleural não é 100% específico, mas quando elevado no líquido (acima do valor de corte laboratorial), aumenta consideravelmente a suspeita de câncer epitelial (especialmente pulmão, mama e trato digestivo), ajudando em casos onde a citologia inicial é inconclusiva.", "option_rationales": {"a": "Incorreta. Marcadores tumorais são auxiliares, não substitutos teciduais.", "b": "Correta. Uso aditivo à citologia para aumentar acurácia.", "c": "Incorreta. TB tem CEA baixo.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Marcadores Tumorais", "CEA"]}'::jsonb, 184, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula ''Gastropleural'' é uma complicação rara após qual cirurgia bariátrica, manifestando-se como derrame pleural purulento persistente?", "options": {"a": "Balão introgástrico.", "b": "Gastrectomia Vertical (Sleeve) ou Bypass Gástrico em Y-de-Roux.", "c": "Lipoaspiração abdominal.", "d": "Apenas em cirurgias de hérnia inguinal.", "e": "Colecistectomia."}, "answer": "b", "rationale": "A fístula do ângulo de His (em cirurgias de Sleeve) pode levar à formação de abscesso subfrênico que erode o diafragma e comunica o estômago com o espaço pleural, causando empiema de difícil manejo que exige drenagem pleural e abdominal simultâneas e correção da fístula digestiva.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação cirúrgica moderna relevante.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Bariátrica", "Fístula Gastropleural", "Empiema"]}'::jsonb, 185, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com Artrite Reumatoide, o derrame pleural tipicamente apresenta níveis MUITO BAIXOS de qual componente do complemento?", "options": {"a": "Apenas C1q.", "b": "C3 e C4 ( níveis de complemento total CH50 frequentemente indetectáveis).", "c": "Apenas C9.", "d": "O complemento está sempre elevado.", "e": "Não existe complemento no líquido pleural."}, "answer": "b", "rationale": "O consumo de complemento no espaço pleural da Artrite Reumatoide é intenso devido à formação in situ de imunocomplexos. Isso ajuda a diferenciar da pleurite lúpica, onde o complemento também pode estar baixo, mas no reumatoide a queda é geralmente mais drástica e associada à glicose baixíssima.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Marcador de atividade inflamatória imune intensa local.", "c": "Incorreta.", "d": "Incorreta. O consumo leva à redução.", "e": "Incorreta. Líquidos exsudativos têm proteínas do complemento."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Artrite Reumatoide", "Complemento"]}'::jsonb, 186, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a ''Linfadenite Tuberculosa'' (Escrófula) e sua relação com o derrame pleural, qual a afirmação correta?", "options": {"a": "Sempre ocorrem juntas.", "b": "São formas extrapulmonares de TB que podem coexistir, especialmente em crianças e pacientes imunossuprimidos, indicando disseminação linfogênica do bacilo.", "c": "A escrófula cura o derrame pleural.", "d": "Apenas o derrame pleural exige tratamento com RIPE.", "e": "O dreno de tórax deve ser colocado no pescoço."}, "answer": "b", "rationale": "Ambas são manifestações de TB extrapulmonar. A coexistência de linfonodomegalia mediastinal ou cervical com derrame pleural reforça a suspeita diagnóstica de TB em casos onde o líquido pleural é linfocítico.", "option_rationales": {"a": "Incorreta. Frequentemente ocorrem isoladas.", "b": "Correta. Visão sistêmica da infecção tuberculosa.", "c": "Incorreta. Uma não cura a outra.", "d": "Incorreta. Ambas exigem o mesmo esquema RIPE.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Infectologia", "Tuberculose", "Extrapulmonar"]}'::jsonb, 187, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Lúpica'' apresenta como achado característico no líquido pleural a presença de células LE (Lupus Erythematosus cells). O que são essas células?", "options": {"a": "Bactérias em forma de lobo.", "b": "Neutrófilos ou macrófagos que fagocitaram núcleos desnaturalizados de outras células (material nuclear opsonizado por anticorpos anti-nucleares).", "c": "Linfócitos gigantes atípicos.", "d": "Fragmentos de talco.", "e": "Células musculares lisas."}, "answer": "b", "rationale": "Embora o diagnóstico moderno do LES se baseie em anticorpos específicos (FAN, anti-DNA, etc), a visualização de células LE no líquido pleural é um achado histórico e raro, mas altamente sugestivo de pleurite lúpica ativa.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição citológica clássica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Reumatologia", "LES", "Células LE"]}'::jsonb, 188, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de Derrame Pleural Persistente após cirurgia de Revascularização do Miocárdio (CABG) com uso da artéria mamária interna?", "options": {"a": "Tuberculose reativada pelo trauma.", "b": "Síndrome de Post-Cardiotomia (inflamação imunológica) ou distúrbios de drenagem linfática/venosa local no hemitórax operado.", "c": "Infecção por pseudomonas sempre.", "d": "Rejeição ao fio de sutura.", "e": "Hipotireoidismo cirúrgico."}, "answer": "b", "rationale": "Derrames pleurais pós-CABG (especialmente à esquerda devido ao uso da mamária esquerda) são muito comuns. Podem ser precoces (por sangramento ou trauma cirúrgico) ou tardios (Síndrome de Dressler/Pós-cardiotomia), respondendo frequentemente a anti-inflamatórios ou corticoides.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Evolução frequente e bem descrita na cirurgia cardíaca.", "c": "Incorreta. O derrame costuma ser estéril inflamatório.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Cardíaca", "CABG", "Dressler"]}'::jsonb, 189, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com ''Insuficiência Renal Crônica'' em hemodiálise, o aparecimento de derrame pleural transudativo súbito BILATERAL, associado a aumento do peso entre as sessões, sugere:", "options": {"a": "Urinotórax.", "b": "Hipervolemia por falha na remoção de fluidos (Congestão sistêmica).", "c": "Infeção pelo vírus da Hepatite C.", "d": "Carcinomatose.", "e": "Pleurite por alumínio."}, "answer": "b", "rationale": "Pacientes anúricos dependem totalmente da ultrafiltração na diálise. O ganho de peso interdialítico excessivo leva à sobrecarga volêmica, aumento da pressão hidrostática e consequente transudação pleural (edema ''interno''). Melhora com ajuste de peso seco na diálise.", "option_rationales": {"a": "Incorreta. Urinotórax é unilateral e associado a obstrução urinária aguda com rim funcionante.", "b": "Correta. Causa diária e comum na nefrologia.", "c": "Incorreta.", "d": "Incorreta. Daria exsudato.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Nefrologia", "Hemodiálise", "Hipervolemia"]}'::jsonb, 190, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Xantomatose Pleural'' é um achado raro caracterizado por depósitos amarelos de gordura na pleura. Qual condição metabólica deve ser investigada?", "options": {"a": "Diabetes Mellitus tipo 1.", "b": "Hiperlipoproteinemias graves (geralmente tipo II ou III).", "c": "Hipotireoidismo subclínico.", "d": "Doença de Wilson.", "e": "Porfiria."}, "answer": "b", "rationale": "Xantomas são depósitos cutâneos ou viscerais de macrófagos carregados de colesterol. Na pleura, são raríssimos, mas indicam distúrbios severos do metabolismo lipídico sistêmico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Correlação metabólica-anatomopatológica.", "c": "Incorreta.", "d": "Incorreta. Cobre.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Metabolismo", "Xantomatose", "Lipídios"]}'::jsonb, 191, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Tuberculose Pleural, qual a principal desvantagem do teste rápido molecular (GeneXpert / TRM-TB) no LÍQUIDO pleural em comparação ao escarro?", "options": {"a": "É muito caro.", "b": "Tem baixa sensibilidade (< 50%) devido à natureza paucibacilar do derrame pleural tuberculoso, embora sua especificidade seja alta.", "c": "Não detecta resistência à rifampicina.", "d": "Só funciona em urina.", "e": "Causa falsos-positivos com bactérias da pneumonia."}, "answer": "b", "rationale": "Embora o GeneXpert seja excelente para escarro (onde há muitos bacilos), no líquido pleural a carga bacteriana é tão baixa que o teste muitas vezes não consegue detectar o DNA do Mycobacterium. Por isso, um TRM-TB negativo no líquido NÃO exclui TB pleural.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Limitação técnica importante para o clínico saber interpretar.", "c": "Incorreta. Detecta resistência se houver material genético suficiente.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "TRM-TB", "GeneXpert"]}'::jsonb, 192, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural purulento ''verde-azulado'' pode ser indicativa de infecção por qual bactéria gram-negativa oportunista?", "options": {"a": "Escherichia coli.", "b": "Pseudomonas aeruginosa (devido à produção de pigmentos como piocianina e pioverdina).", "c": "Haemophilus influenzae.", "d": "Streptococcus pneumoniae.", "e": "Moraxella catarrhalis."}, "answer": "b", "rationale": "A Pseudomonas produz pigmentos coloridos que podem tingir o pus do empiema. É uma pista macroscópica importante para o início de cobertura antibiótica antipseudomonas precoce enquanto se aguarda o antibiograma.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Pista microbiológica macroscópica clássica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Infectologia", "Pseudomonas", "Pigmentos"]}'::jsonb, 193, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com ''Artroplastia de Quadril ou Joelho'' recente, a ocorrência de derrame pleural súbito bilateral com hipoxemia e rash petequial axilar sugere qual diagnóstico de exclusão?", "options": {"a": "Empiema hospitalar.", "b": "Síndrome da Embolia Gordurosa (SEG).", "c": "Tuberculose óssea.", "d": "Reação ao cimento ortopédico.", "e": "Linfangiomatose."}, "answer": "b", "rationale": "A SEG ocorre após trauma ou cirurgia de ossos longos/grandes articulações. Os glóbulos de gordura atingem o pulmão desencadeando uma cascata inflamatória grave (pneumonite gordurosa) que pode cursar com derrames pleurais exsudativos e sofrimento respiratório agudo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Quadro clínico-cirúrgico clássico em ortopedia/pneumo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Ortopedia", "Embolia Gordurosa", "Derrame Pleural"]}'::jsonb, 194, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O ''Derrame Pleural Paraneoplásico'' (Efusão Paramaligna) difere da Efusão Maligna Verdadeira porque:", "options": {"a": "O paraneoplásico é causado pelo talco.", "b": "O paraneoplásico ocorre por mecanismos indiretos (obstrução linfática regional, pneumonia obstrutiva ou hipoalbuminemia) e NÃO contém células neoplásicas na pleura ou no líquido.", "c": "É sempre purulento.", "d": "Só ocorre em crianças.", "e": "Cura-se com aspirina."}, "answer": "b", "rationale": "Essa distinção é vital para o estadiamento. Se o líquido for paraneoplásico (células malignas negativas em múltiplas citologias e biópsias), o paciente ainda pode ser candidato a tratamento curativo (estágio menor). Se for maligno (M1a), o tratamento é paliativo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição oncológica fundamental para estadiamento (M0 vs M1).", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Estadiamento", "Mecanismo"]}'::jsonb, 195, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal limitação do uso da ''Escrituração por Imagem'' (Escore RAPID) no manejo clínico dos derrames pleurais?", "options": {"a": "Só funciona para câncer.", "b": "O escore RAPID (Renal, Age, Purulence, Infection source, Dietary) é validado especificamente para prever mortalidade em pacientes com Empiema/Derrame Parapneumônico, não sendo aplicável para transudatos ou câncer.", "c": "É impossível de decorar.", "d": "Exige ressonância magnética nuclear.", "e": "Só pode ser usado por cirurgiões."}, "answer": "b", "rationale": "O escore RAPID ajuda a estratificar o risco de morte em 3 meses para empiema pleural. Variáveis como Ureia (Renal), Idade, Purulência do líquido, Local da infecção (Comunitário vs Nosocomial) e Nível de Albumina são as ferramentas de cálculo. Conhecer seu público alvo é essencial.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Validação clínica específica de escores prognósticos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Escore RAPID", "Empiema", "Prognóstico"]}'::jsonb, 196, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Crônica Não-Específica'' é um laudo comum de biópsia pleural que não detecta câncer ou TB. Qual a conduta recomendada se a suspeita clínica de malignidade for alta?", "options": {"a": "Dar alta ao paciente.", "b": "Repetir a investigação através de biópsia guiada por videotoracoscopia (VATS) para obter amostras maiores e mais representativas da pleura parietal e visceral.", "c": "Tratar como pneumonia por 2 anos.", "d": "Trocar o patologista.", "e": "Fazer apenas gargarejos."}, "answer": "b", "rationale": "Cerca de 30-40% das biópsias inespecíficas iniciais em pacientes com suspeita de câncer acabam revelando malignidade em investigações subsequentes mais invasivas. O acompanhamento rigoroso ou a cirurgia diagnóstica (VATS) são obrigatórios.", "option_rationales": {"a": "Incorreta. Negligência diagnóstica.", "b": "Correta. Fluxograma de investigação de pleura de origem indeterminada.", "c": "Incorreta.", "d": "Incorreta. Embora a revisão de lâminas seja válida, a re-amostragem cirúrgica é o passo definitivo.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Diagnóstico", "Propedeutica", "Indeterminado"]}'::jsonb, 197, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal diferença entre o ''Hemotórax'' e o ''Derrame Pleural Sero-hemorrágico'' na análise laboratorial?", "options": {"a": "Apenas a cor.", "b": "O Hemotórax é definido por um hematócrito do líquido pleural ≥ 50% do hematócrito do sangue periférico.", "c": "O sero-hemorrágico é comum no câncer, enquanto o hemotórax é quase sempre traumático.", "d": "Ambas as alternativas B e C estão corretas e se complementam no raciocínio clínico.", "e": "Não há diferença."}, "answer": "d", "rationale": "Esta é uma distinção técnica crucial. Pouco sangue (1-10 mL) já deixa o líquido vermelho (sero-hemorrágico). O hemotórax real exige uma concentração de hemácias significativa em relação ao sangue do paciente, mudando drasticamente a conduta (drenagem agressiva).", "option_rationales": {"a": "Incorreta.", "b": "Incorreta (sozinha).", "c": "Incorreta (sozinha).", "d": "Correta. Síntese do conhecimento técnico-clínico sobre sangue na pleura.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Hematologia", "Hemotórax", "Critérios"]}'::jsonb, 198, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Encerrando o estudo dos derrames pleurais: Qual é o ''sinal radiográfico'' que indica a presença de um grande volume de líquido pleural em uma radiografia de tórax realizada em DECÚBITO DORSAL (paciente deitado na UTI)?", "options": {"a": "Parábola de Damoiseau.", "b": "Velamento difuso (Haze) de um hemitórax, com preservação da visualização dos vasos pulmonares através da ''névoa'' e ausência de desvio de estruturas mediastinais.", "c": "Nível hidroaéreo retilíneo.", "d": "Desaparecimento do coração.", "e": "Presença de bolhas de sabão."}, "answer": "b", "rationale": "No paciente deitado, o líquido se espalha uniformemente por toda a superfície posterior do pulmão. O resultado é um aumento da densidade global (um ''véu'' branco) sobre o hemitórax acometido, diferente dos níveis localizados do paciente em pé.", "option_rationales": {"a": "Incorreta. Sinal do derrame livre no paciente em ortostatismo.", "b": "Correta. Interpretação radiológica crítica no paciente crítico acamado.", "c": "Incorreta. Indica hidropneumotórax.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "UTI", "Semiologia Radiológica"]}'::jsonb, 199, 'draft');